// Builds the one script the search page loads: the normaliser and the engine (the same files the tests run in
// Node) followed by the page behaviour, wrapped so nothing leaks into the page. Plain concatenation: the only
// transformation is dropping `import` lines and the `export` keyword, so what runs in the browser is the tested code.

import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const stripModuleSyntax = (source) => source
  .replace(/^import[^;]*;[ \t]*\r?\n/gm, '')
  .replace(/^export\s+(?=(?:async\s+)?(?:function|const|let|class)\b)/gm, '')
  .replace(/^export\s*\{[^}]*\};?[ \t]*\r?\n/gm, '');

/** @returns {{ engine: string, ui: string, script: string }} */
export function searchBundle(rootDir) {
  const read = (...parts) => readFileSync(join(rootDir, ...parts), 'utf8');
  const engine = `${stripModuleSyntax(read('src', 'core', 'search-text.mjs'))}\n${stripModuleSyntax(read('src', 'core', 'search-engine.mjs'))}`;
  const ui = read('public', 'assets', 'search-ui.js');
  const script = `/* ABDO search: normaliser + engine + page behaviour. Generated by the build (src/lib/search-bundle.mjs); do not edit. */\n(function () {\n'use strict';\n${engine}\n${ui}\n})();\n`;
  return { engine, ui, script };
}
